import { useEffect } from 'react';
import { hasValidAuthToken } from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import { logout } from '../../store/slices/authSlice';

declare global {
  interface Window {
    __LINM_LOGOUT_IN_PROGRESS__?: boolean;
  }
}

/**
 * When Nav or another MFE clears tokens without dispatching Home logout,
 * keep Redux auth slice aligned so PublicRoute does not bounce back to the app.
 *
 * Guard: skip dispatch when ShellLogoutHandler is already running (path=/logout)
 * or has the global flag set, to avoid racing the thunk and sending a 401 logout
 * request to the backend.
 */
export const AuthSessionSync: React.FC = () => {
  const dispatch = useAppDispatch();
  const isAuthenticated = useAppSelector((state) => state.auth.isAuthenticated);
  const logoutLoading = useAppSelector((state) => state.auth.logoutLoading);

  useEffect(() => {
    const sync = () => {
      // If /logout flow is already in progress (ShellLogoutHandler), skip.
      if (window.__LINM_LOGOUT_IN_PROGRESS__) return;
      if (window.location.pathname === '/logout') return;
      // If our own logout thunk is still running, skip.
      if (logoutLoading) return;

      if (!hasValidAuthToken() && isAuthenticated) {
        void dispatch(logout());
      }
    };

    sync();
    window.addEventListener('linm:auth:token-changed', sync);
    window.addEventListener('linm:auth:changed', sync);
    return () => {
      window.removeEventListener('linm:auth:token-changed', sync);
      window.removeEventListener('linm:auth:changed', sync);
    };
  }, [dispatch, isAuthenticated, logoutLoading]);

  return null;
};
