const ACCOUNT_ROLE_LABELS: Record<string, string> = {
  admin: 'Quản trị',
  manager: 'Quản lý',
  staff: 'Nhân viên',
};

export function getAccountRoleLabel(role?: string): string {
  const normalized = role?.toLowerCase() ?? '';
  return ACCOUNT_ROLE_LABELS[normalized] ?? role ?? '—';
}
