padding: 32px 24px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 32px;\r\n}\r\n\r\n/* ── Prominent Install CTA card ── */\r\n.ctaCard {\r\n  display: flex;\r\n  gap: 18px;\r\n  padding: 20px 24px;\r\n  background: white;\r\n  border: 1px solid var(--ds-color-border, #BABCBE);\r\n  border-radius: 12px;\r\n  align-items: flex-start;\r\n}\r\n\r\n.ctaCardActive {\r\n  background: var(--ds-color-primary-bg, rgba(0,52,104,0.08));\r\n  border-color: var(--ds-color-primary-bg, rgba(0,52,104,0.08));\r\n}\r\n\r\n.ctaCardIos {\r\n  background: var(--ds-color-bg-subtle, #F6F6F6);\r\n  border-color: var(--ds-color-border, #BABCBE);\r\n}\r\n\r\n.ctaIcon {\r\n  width: 40px;\r\n  height: 40px;\r\n  border-radius: 10px;\r\n  background: var(--ds-color-primary, #2563eb);\r\n  color: white;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  font-size: 18px;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.ctaCardActive .ctaIcon {\r\n  background: var(--ds-color-primary, #2563eb);\r\n}\r\n\r\n.ctaCardIos .ctaIcon {\r\n  background: var(--ds-color-text-secondary, #4A4A4A);\r\n}\r\n\r\n.ctaIconSuccess {\r\n  background: var(--ds-color-success, #0D8240) !important;\r\n}\r\n\r\n.ctaBody {\r\n  flex: 1;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 8px;\r\n}\r\n\r\n.ctaTitle {\r\n  font-size: 16px;\r\n  font-weight: 600;\r\n  color: var(--ds-color-text-heading, #1A1A1A);\r\n}\r\n\r\n.ctaDesc {\r\n  font-size: var(--ds-font-size-input-desktop, 14px);\r\n  color: var(--ds-color-text-tertiary, #6D6D6D);\r\n  line-height: 1.5;\r\n}\r\n\r\n.ctaBtn {\r\n  align-self: flex-start;\r\n  margin-top: 6px;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  padding: 10px 22px;\r\n  background: var(--ds-color-primary, #2563eb);\r\n  color: white;\r\n  border: none;\r\n  border-radius: 8px;\r\n  font-size: 14px;\r\n  font-weight: 600;\r\n  cursor: pointer;\r\n  transition: background 0.15s, transform 0.1s;\r\n}\r\n\r\n.ctaBtn:hover:not(:disabled) {\r\n  background: var(--ds-color-primary, #2563eb);\r\n}\r\n\r\n.ctaBtn:active:not(:disabled) {\r\n  transform: scale(0.97);\r\n}\r\n\r\n.ctaBtn:disabled {\r\n  opacity: 0.65;\r\n  cursor: not-allowed;\r\n}\r\n\r\n.ctaStepsList {\r\n  margin: 8px 0 0;\r\n  padding-left: 20px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 6px;\r\n  font-size: var(--ds-font-size-input-desktop, 14px);\r\n  color: var(--ds-color-text-secondary, #4A4A4A);\r\n  line-height: 1.55;\r\n}\r\n\r\n/* ── Header ── */\r\n.header {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 8px;\r\n}\r\n\r\n.breadcrumb {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  font-size: var(--ds-font-size-input-desktop, 14px);\r\n  color: var(--ds-color-text-tertiary, #6D6D6D);\r\n}\r\n\r\n.breadcrumbLink {\r\n  background: none;\r\n  border: none;\r\n  cursor: pointer;\r\n  color: var(--ds-color-primary, #2563eb);\r\n  padding: 0;\r\n  font-size: var(--ds-font-size-input-desktop, 14px);\r\n  text-decoration: none;\r\n}\r\n\r\n.breadcrumbLink:hover {\r\n  text-decoration: underline;\r\n}\r\n\r\n.title {\r\n  font-size: 26px;\r\n  font-weight: 700;\r\n  color: var(--ds-color-text-heading, #1A1A1A);\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 12px;\r\n  margin: 0;\r\n}\r\n\r\n.titleIcon {\r\n  color: var(--ds-color-primary, #2563eb);\r\n}\r\n\r\n.subtitle {\r\n  font-size: 16px;\r\n  color: var(--ds-color-text-tertiary, #6D6D6D);\r\n  margin: 0;\r\n}\r\n\r\n/* ── Status Banner ── */\r\n.statusBanner {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 12px;\r\n  padding: 16px 20px;\r\n  border-radius: 12px;\r\n  font-size: 14px;\r\n  font-weight: 500;\r\n}\r\n\r\n.statusBannerGranted {\r\n  background: var(--ds-color-success-bg, #E5F4EA);\r\n  border: 1px solid var(--ds-color-success-bg, #E5F4EA);\r\n  color: var(--ds-color-success, #0D8240);\r\n}\r\n\r\n.statusBannerDefault {\r\n  background: var(--ds-color-primary-bg, rgba(0,52,104,0.08));\r\n  border: 1px solid var(--ds-color-primary-bg, rgba(0,52,104,0.08));\r\n  color: var(--ds-color-primary, #2563eb);\r\n}\r\n\r\n.statusBannerIcon {\r\n  font-size: 18px;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.statusBannerText {\r\n  flex: 1;\r\n}\r\n\r\n.statusBannerAction {\r\n  background: var(--ds-color-primary, #2563eb);\r\n  color: white;\r\n  border: none;\r\n  border-radius: 8px;\r\n  padding: 8px 18px;\r\n  font-size: var(--ds-font-size-input-desktop, 14px);\r\n  font-weight: 600;\r\n  cursor: pointer;\r\n  transition: background 0.15s;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  white-space: nowrap;\r\n}\r\n\r\n.statusBannerAction:hover {\r\n  background: var(--ds-color-primary, #2563eb);\r\n}\r\n\r\n.statusBannerAction:disabled {\r\n  opacity: 0.6;\r\n  cursor: not-allowed;\r\n}\r\n\r\n/* ── Card ── */\r\n.card {\r\n  background: white;\r\n  border: 1px solid var(--ds-color-border, #BABCBE);\r\n  border-radius: 12px;\r\n  overflow: hidden;\r\n}\r\n\r\n.cardHeader {\r\n  padding: 20px 24px;\r\n  border-bottom: 1px solid var(--ds-color-border, #BABCBE);\r\n  background: var(--ds-color-bg-subtle, #F6F6F6);\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 10px;\r\n}\r\n\r\n.cardHeaderIcon {\r\n  font-size: 18px;\r\n  color: var(--ds-color-primary, #2563eb);\r\n}\r\n\r\n.cardTitle {\r\n  font-size: 16px;\r\n  font-weight: 600;\r\n  color: var(--ds-color-text-heading, #1A1A1A);\r\n  margin: 0;\r\n}\r\n\r\n.cardBody {\r\n  padding: 24px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 20px;\r\n}\r\n\r\n/* ── Benefits Grid ── */\r\n.benefitsGrid {\r\n  display: grid;\r\n  grid-template-columns: repeat(2, 1fr);\r\n  gap: 16px;\r\n}\r\n\r\n.benefitItem {\r\n  display: flex;\r\n  align-items: flex-start;\r\n  gap: 14px;\r\n  padding: 16px;\r\n  background: var(--ds-color-bg-subtle, #F6F6F6);\r\n  border-radius: 8px;\r\n  border: 1px solid var(--ds-color-border, #BABCBE);\r\n}\r\n\r\n.benefitIcon {\r\n  font-size: 20px;\r\n  color: var(--ds-color-primary, #2563eb);\r\n  flex-shrink: 0;\r\n  margin-top: 2px;\r\n  width: 24px;\r\n  text-align: center;\r\n}\r\n\r\n.benefitTitle {\r\n  font-size: 14px;\r\n  font-weight: 600;\r\n  color: var(--ds-color-text-heading, #1A1A1A);\r\n  margin-bottom: 4px;\r\n}\r\n\r\n.benefitDesc {\r\n  font-size: var(--ds-font-size-input-desktop, 14px);\r\n  color: var(--ds-color-text-tertiary, #6D6D6D);\r\n  line-height: 1.45;\r\n}\r\n\r\n/* ── Platform tabs ── */\r\n.platformTabs {\r\n  display: flex;\r\n  gap: 8px;\r\n  border-bottom: 2px solid var(--ds-color-border, #BABCBE);\r\n  padding-bottom: 0;\r\n  margin-bottom: 20px;\r\n}\r\n\r\n.platformTab {\r\n  padding: 10px 18px;\r\n  border: none;\r\n  background: none;\r\n  cursor: pointer;\r\n  font-size: var(--ds-font-size-input-desktop, 14px);\r\n  font-weight: 500;\r\n  color: var(--ds-color-text-tertiary, #6D6D6D);\r\n  border-bottom: 2px solid transparent;\r\n  margin-bottom: -2px;\r\n  transition: color 0.15s, border-color 0.15s;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n}\r\n\r\n.platformTab:hover {\r\n  color: var(--ds-color-primary, #2563eb);\r\n}\r\n\r\n.platformTabActive {\r\n  color: var(--ds-color-primary, #2563eb);\r\n  border-bottom-color: var(--ds-color-primary, #2563eb);\r\n  font-weight: 600;\r\n}\r\n\r\n/* ── Steps ── */\r\n.steps {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 16px;\r\n}\r\n\r\n.step {\r\n  display: flex;\r\n  gap: 16px;\r\n  align-items: flex-start;\r\n}\r\n\r\n.stepNumber {\r\n  width: 32px;\r\n  height: 32px;\r\n  border-radius: 50%;\r\n  background: var(--ds-color-primary, #2563eb);\r\n  color: white;\r\n  font-size: var(--ds-font-size-input-desktop, 14px);\r\n  font-weight: 700;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  flex-shrink: 0;\r\n  margin-top: 2px;\r\n}\r\n\r\n.stepContent {\r\n  flex: 1;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 6px;\r\n}\r\n\r\n.stepTitle {\r\n  font-size: 16px;\r\n  font-weight: 600;\r\n  color: var(--ds-color-text-heading, #1A1A1A);\r\n  margin: 0;\r\n}\r\n\r\n.stepDesc {\r\n  font-size: var(--ds-font-size-input-desktop, 14px);\r\n  color: var(--ds-color-text-tertiary, #6D6D6D);\r\n  line-height: 1.55;\r\n  margin: 0;\r\n}\r\n\r\n.stepCode {\r\n  display: inline-block;\r\n  background: var(--ds-color-bg-subtle, #F6F6F6);\r\n  border: 1px solid var(--ds-color-border, #BABCBE);\r\n  border-radius: 6px;\r\n  padding: 4px 10px;\r\n  font-family: 'SF Mono', 'Fira Code', 'Consolas', monospace;\r\n  font-size: 12px;\r\n  color: var(--ds-color-text-heading, #1A1A1A);\r\n  margin-top: 4px;\r\n}\r\n\r\n/* ── Alert box ── */\r\n.alertBox {\r\n  display: flex;\r\n  gap: 12px;\r\n  padding: 14px 16px;\r\n  border-radius: 8px;\r\n  font-size: var(--ds-font-size-input-desktop, 14px);\r\n  line-height: 1.5;\r\n}\r\n\r\n.alertInfo {\r\n  background: var(--ds-color-primary-bg, rgba(0,52,104,0.08));\r\n  border: 1px solid var(--ds-color-primary-bg, rgba(0,52,104,0.08));\r\n  color: var(--ds-color-primary, #2563eb);\r\n}\r\n\r\n.alertWarning {\r\n  background: var(--ds-color-warning-bg, #FDF3E2);\r\n  border: 1px solid var(--ds-color-warning-bg, #FDF3E2);\r\n  color: var(--ds-color-warning, #EB9114);\r\n}\r\n\r\n.alertSuccess {\r\n  background: var(--ds-color-success-bg, #E5F4EA);\r\n  border: 1px solid var(--ds-color-success-bg, #E5F4EA);\r\n  color: var(--ds-color-success, #0D8240);\r\n}\r\n\r\n.alertIcon {\r\n  font-size: 16px;\r\n  flex-shrink: 0;\r\n  margin-top: 2px;\r\n}\r\n\r\n/* ── Verify steps ── */\r\n.verifySteps {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 8px;\r\n}\r\n\r\n.verifyItem {\r\n  display: flex;\r\n  align-items: flex-start;\r\n  gap: 12px;\r\n  font-size: var(--ds-font-size-input-desktop, 14px);\r\n  color: var(--ds-color-text-secondary, #4A4A4A);\r\n  line-height: 1.55;\r\n}\r\n\r\n.verifyIcon {\r\n  color: var(--ds-color-primary, #2563eb);\r\n  font-size: 14px;\r\n  margin-top: 3px;\r\n  flex-shrink: 0;\r\n}\r\n\r\n/* ── Troubleshoot table ── */\r\n.troubleshootTable {\r\n  width: 100%;\r\n  border-collapse: collapse;\r\n  font-size: var(--ds-font-size-input-desktop, 14px);\r\n}\r\n\r\n.troubleshootTable th {\r\n  text-align: left;\r\n  padding: 10px 14px;\r\n  background: var(--ds-color-bg-subtle, #F6F6F6);\r\n  color: var(--ds-color-text-secondary, #4A4A4A);\r\n  font-weight: 600;\r\n  border-bottom: 1px solid var(--ds-color-border, #BABCBE);\r\n}\r\n\r\n.troubleshootTable td {\r\n  padding: 12px 14px;\r\n  border-bottom: 1px solid var(--ds-color-border, #BABCBE);\r\n  color: var(--ds-color-text-secondary, #4A4A4A);\r\n  vertical-align: top;\r\n  line-height: 1.5;\r\n}\r\n\r\n.troubleshootTable tr:last-child td {\r\n  border-bottom: none;\r\n}\r\n\r\n.troubleshootTable tr:nth-child(even) td {\r\n  background: var(--ds-color-bg-subtle, #F6F6F6);\r\n}\r\n\r\n/* ── Related links ── */\r\n.relatedLinks {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 12px;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.relatedLabel {\r\n  font-size: var(--ds-font-size-input-desktop, 14px);\r\n  color: var(--ds-color-text-tertiary, #6D6D6D);\r\n  font-weight: 500;\r\n}\r\n\r\n.relatedLink {\r\n  background: none;\r\n  border: 1px solid var(--ds-color-border, #BABCBE);\r\n  border-radius: 8px;\r\n  padding: 6px 14px;\r\n  font-size: var(--ds-font-size-input-desktop, 14px);\r\n  color: var(--ds-color-primary, #2563eb);\r\n  cursor: pointer;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  transition: background 0.15s, border-color 0.15s;\r\n}\r\n\r\n.relatedLink:hover {\r\n  background: var(--ds-color-bg-subtle, #F6F6F6);\r\n  border-color: var(--ds-color-primary-bg, rgba(0,52,104,0.08));\r\n}\r\n\r\n/* ── Back button ── */\r\n.backBtn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  padding: 10px 18px;\r\n  background: none;\r\n  border: 1px solid var(--ds-color-border, #BABCBE);\r\n  border-radius: 8px;\r\n  cursor: pointer;\r\n  font-size: var(--ds-font-size-input-desktop, 14px);\r\n  color: var(--ds-color-text-secondary, #4A4A4A);\r\n  transition: background 0.15s, color 0.15s;\r\n  align-self: flex-start;\r\n}\r\n\r\n.backBtn:hover {\r\n  background: var(--ds-color-bg-subtle, #F6F6F6);\r\n  color: var(--ds-color-text-heading, #1A1A1A);\r\n}\r\n\r\n@media (max-width: 640px) {\r\n  .page {\r\n    padding: 16px;\r\n  }\r\n\r\n  .title {\r\n    font-size: 22px;\r\n  }\r\n\r\n  .benefitsGrid {\r\n    grid-template-columns: 1fr;\r\n  }\r\n\r\n  .platformTabs {\r\n    overflow-x: auto;\r\n    -webkit-overflow-scrolling: touch;\r\n  }\r\n\r\n  .troubleshootTable {\r\n    display: block;\r\n    overflow-x: auto;\r\n  }\r\n\r\n  .relatedLinks {\r\n    flex-direction: column;\r\n    align-items: flex-start;\r\n  }\r\n}\r\n\r\n/* ════════════════════════════════════════════════════════════════════\r\n   TWO-SECTION LAYOUT (Phần 1 / Phần 2)\r\n════════════════════════════════════════════════════════════════════ */\r\n\r\n.sectionCard {\r\n  background: var(--ds-color-bg-white, #FFFFFF);\r\n  border: 1px solid var(--ds-color-border, #BABCBE);\r\n  border-radius: 12px;\r\n  overflow: hidden;\r\n  margin-bottom: 20px;\r\n}\r\n\r\n.sectionHeader {\r\n  padding: 14px 24px;\r\n  border-bottom: 1px solid var(--ds-color-border, #BABCBE);\r\n  background: var(--ds-color-bg-subtle, #F6F6F6);\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 10px;\r\n}\r\n\r\n.sectionBadge {\r\n  font-size: 12px;\r\n  font-weight: 700;\r\n  padding: 3px 9px;\r\n  background: var(--ds-color-primary, #2563eb);\r\n  color: var(--ds-color-bg-white, #FFFFFF);\r\n  border-radius: var(--ds-radius-full, 9999px);\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.04em;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.sectionHeaderIcon {\r\n  color: var(--ds-color-primary, #2563eb);\r\n  font-size: 16px;\r\n}\r\n\r\n.sectionTitle {\r\n  font-size: 16px;\r\n  font-weight: 600;\r\n  color: var(--ds-color-text-heading, #1A1A1A);\r\n  margin: 0;\r\n}\r\n\r\n.secti